function-point.pseudocode:
WEIGHTS = {  # 복잡도별 가중치 (저, 중, 고)
    'EI': (3, 4, 6), 'EO': (4, 5, 7), 'EQ': (3, 4, 6),
    'ILF': (7, 10, 15), 'EIF': (5, 7, 10),
}
LEVEL = {'low': 0, 'avg': 1, 'high': 2}

def unadjusted_fp(functions):
    # functions: [('EI', 'avg'), ('ILF', 'low'), ...]
    return sum(WEIGHTS[t][LEVEL[c]] for t, c in functions)

def adjusted_fp(ufp, gsc_scores):
    # IFPUG: 일반 시스템 특성 14개, 각 0~5점
    vaf = 0.65 + 0.01 * sum(gsc_scores)  # 0.65~1.35
    return ufp * vaf

# 예: EI 평균 2개 + ILF 저 1개 → UFP = 4*2 + 7 = 15

functional-dependency.pseudocode:
def closure(attrs, fds):
    # attrs: 속성 집합 X, fds: [(왼쪽 집합, 오른쪽 집합), ...]
    result = set(attrs)  # 반사: X ⊆ X+
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            # 결정자가 모두 포함되면 종속자 추가 (이행)
            if lhs <= result and not rhs <= result:
                result |= rhs
                changed = True
    return result

def is_superkey(attrs, all_attrs, fds):
    return closure(attrs, fds) >= all_attrs  # X+ = 전체
